bat_estado = []

def bat_configurar(pin, r1, r2, referencia, bloque):
    if not (r1 > 0 and r2 > 0 and referencia > 0):
        rb_fail(bloque, "R1, R2 y referencia deben ser mayores que cero")
    adc = ADC(Pin(pin))
    if hasattr(adc, "atten"):
        adc.atten(ADC.ATTN_11DB)
    if hasattr(adc, "width"):
        adc.width(ADC.WIDTH_12BIT)
    bat_estado[:] = [adc, r1, r2, referencia]

def bat_voltaje(bloque):
    if not bat_estado:
        rb_fail(bloque, "Configura la batería al iniciar")
    adc, r1, r2, referencia = bat_estado
    total = 0
    for indice in range(8):
        if hasattr(adc, "read_uv"):
            total += adc.read_uv() / 1000000
        else:
            total += adc.read() / 4095 * referencia
    return total / 8 * (r1 + r2) / r2

def bat_porcentaje(minimo, maximo, bloque):
    minimo = rb_finite(minimo, bloque)
    maximo = rb_finite(maximo, bloque)
    if not maximo > minimo:
        rb_fail(bloque, "El voltaje máximo debe ser mayor que el mínimo")
    return max(0, min(100, (bat_voltaje(bloque) - minimo) * 100 / (maximo - minimo)))

