ina_buses = {}
def ina_bus(sda, scl, bloque):
    # Un bus por par de pines; los sensores que comparten SDA/SCL comparten el bus.
    clave = (sda, scl)
    if clave not in ina_buses:
        try:
            if len(ina_buses) < 2:
                ina_buses[clave] = I2C(len(ina_buses), scl=Pin(scl), sda=Pin(sda), freq=400000)
            else:
                ina_buses[clave] = SoftI2C(scl=Pin(scl), sda=Pin(sda), freq=400000)
        except (ValueError, OSError) as error:
            rb_fail(bloque, "No se pudo iniciar I2C en SDA %s / SCL %s: %s" % (sda, scl, error))
    return ina_buses[clave]
ina_estado = []

def ina_error(direccion, bloque):
    mensajes = ("No se encontró el INA219 en 0x40", "No se encontró el INA219 en 0x41", "No se encontró el INA219 en 0x42", "No se encontró el INA219 en 0x43", "No se encontró el INA219 en 0x44", "No se encontró el INA219 en 0x45")
    rb_fail(bloque, mensajes[direccion - 0x40])

def ina_configurar(sda, scl, direccion, bloque):
    direccion = int(direccion, 16)
    bus = ina_bus(sda, scl, bloque)
    ina_estado[:] = []
    try:
        bus.readfrom_mem(direccion, 0, 2)
        bus.writeto_mem(direccion, 0, bytes((0x39, 0x9F)))
        bus.writeto_mem(direccion, 5, bytes((0x10, 0x00)))
    except OSError:
        ina_error(direccion, bloque)
    ina_estado[:] = [bus, direccion]

def ina_leer(registro, bloque):
    if not ina_estado:
        rb_fail(bloque, "Configura el INA219 al iniciar")
    bus, direccion = ina_estado
    try:
        datos = bus.readfrom_mem(direccion, registro, 2)
    except OSError:
        ina_error(direccion, bloque)
    valor = datos[0] * 256 + datos[1]
    if registro == 2:
        if valor & 1:
            rb_fail(bloque, "Desbordamiento de medición INA219")
        return (valor >> 3) * 0.004
    if registro == 4:
        return (valor - 65536 if valor & 0x8000 else valor) * 0.1
    return valor * 2

inline bool rb_i2c_read(TwoWire& bus, uint8_t address, uint8_t reg, uint8_t* data, uint8_t count) {
    bus.beginTransmission(address); bus.write(reg);
    if (bus.endTransmission(false) != 0) return false;
    if (bus.requestFrom(address, count) != count) return false;
    for (uint8_t i = 0; i < count; i++) { int value = bus.read(); if (value < 0) return false; data[i] = value; } return true;
}
inline bool rb_i2c_write(TwoWire& bus, uint8_t address, uint8_t reg, uint8_t value) {
    bus.beginTransmission(address); bus.write(reg); bus.write(value); return bus.endTransmission() == 0;
}

static TwoWire* ina_bus_actual = nullptr;
static uint8_t ina_direccion = 0x40;
inline void ina_error(const char* bloque) {
    const char* mensajes[] = {"No se encontró el INA219 en 0x40", "No se encontró el INA219 en 0x41", "No se encontró el INA219 en 0x42", "No se encontró el INA219 en 0x43", "No se encontró el INA219 en 0x44", "No se encontró el INA219 en 0x45"};
    rb_fail(bloque, mensajes[ina_direccion - 0x40]);
}
inline bool ina_escribir(TwoWire& bus, uint8_t registro, uint16_t valor) {
    // El helper compartido escribe un byte; estos registros exigen dos en la misma transacción.
    bus.beginTransmission(ina_direccion);
    bus.write(registro);
    bus.write(uint8_t(valor >> 8));
    bus.write(uint8_t(valor));
    return bus.endTransmission() == 0;
}
inline void ina_configurar(TwoWire& bus, const String& direccion, const char* bloque) {
    ina_bus_actual = nullptr;
    ina_direccion = uint8_t(strtoul(direccion.c_str(), nullptr, 16));
    uint8_t datos[2];
    if (!rb_i2c_read(bus, ina_direccion, 0, datos, 2) || !ina_escribir(bus, 0, 0x399F) || !ina_escribir(bus, 5, 4096)) { ina_error(bloque); return; }
    ina_bus_actual = &bus;
}
inline float ina_leer(uint8_t registro, const char* bloque) {
    if (!ina_bus_actual) { rb_fail(bloque, "Configura el INA219 al iniciar"); return 0; }
    uint8_t datos[2];
    if (!rb_i2c_read(*ina_bus_actual, ina_direccion, registro, datos, 2)) { ina_error(bloque); return 0; }
    uint16_t valor = uint16_t(datos[0]) << 8 | datos[1];
    if (registro == 2) {
        if (valor & 1) { rb_fail(bloque, "Desbordamiento de medición INA219"); return 0; }
        return (valor >> 3) * 0.004f;
    }
    if (registro == 4) return (valor & 0x8000 ? int32_t(valor) - 65536 : int32_t(valor)) * 0.1f;
    return valor * 2.0f;
}
